import manifest from "./media-manifest.json";

// Generated by scripts/optimize-media.mjs. Maps original public media URLs to
// lighter, content-hashed display copies under /optimized.
const optimizedMedia: Record<string, string> = manifest;

/**
 * Returns the optimized display URL for a bundled image or video, or the
 * original URL when no copy exists (remote URLs, data URLs, new files).
 * Display only: try-on requests must keep sending the original product path.
 */
export function displayMediaUrl(src: string): string {
  return optimizedMedia[src] ?? src;
}

/** Returns the still poster frame generated for a bundled video, if any. */
export function videoPosterUrl(src: string): string | undefined {
  return optimizedMedia[`${src}#poster`];
}

/** Every optimized display URL, used to warm the browser cache. */
export function allDisplayMediaUrls(): string[] {
  return Object.values(optimizedMedia);
}
